import json,os,html,pathlib,shutil,xml.etree.ElementTree as ET
P=pathlib.Path(__file__).parent; D=P/'dist'; D.mkdir(exist_ok=True)
BASE=os.environ.get('SITE_URL','https://nalssam.github.io/nalssam-life').rstrip('/')
posts=json.loads((P/'content/posts.json').read_text()); cats=['AI 활용','디지털 팁','일상 꿀팁','추천 가전제품','추천 맛집','추천 카페','추천 여행지','추천 화장품','추천 책']; e=html.escape
assert len({p['slug'] for p in posts})==len(posts)
for p in posts:
 assert p['category'] in cats
 assert p['slug'].replace('-','').isalnum()
def head(title,desc,path='',schema=None,noindex=False):
 return f'''<!doctype html><html lang="ko"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{e(title)} | 날쌤의 쓸모 있는 기록</title><meta name="description" content="{e(desc)}"><link rel="canonical" href="{BASE}/{path}"><meta property="og:title" content="{e(title)}"><meta property="og:description" content="{e(desc)}"><meta property="og:url" content="{BASE}/{path}"><meta property="og:type" content="{'article' if schema else 'website'}"><meta name="theme-color" content="#f6f5f0"><link rel="icon" href="{BASE}/assets/icon.svg"><link rel="stylesheet" href="{BASE}/assets/style.css">{('<meta name="robots" content="noindex">' if noindex else '')}{('<script type="application/ld+json">'+json.dumps(schema,ensure_ascii=False).replace('<','\\u003c')+'</script>' if schema else '')}</head><body><a class="skip" href="#main">본문으로 이동</a><header><a class="brand" href="{BASE}/"><span class="brand-icon">n.</span><span>날쌤의 기록<small>NOTES FOR A BETTER EVERYDAY</small></span></a><nav aria-label="주 메뉴"><a href="{BASE}/#browse">모든 기록</a><a href="{BASE}/?saved=1#browse">모아보기 <span aria-hidden="true">↗</span></a><a href="{BASE}/about/">날쌤 소개</a></nav></header>'''
def foot(): return f'<footer><a class="brand" href="{BASE}/">날쌤의 쓸모 있는 기록.</a><p>배운 것, 써 본 것, 다시 찾고 싶은 것.</p><div>© 2026 날쌤 · <a href="{BASE}/admin/">관리자</a> · <a href="{BASE}/feed.xml">RSS</a></div></footer><div id="toast" role="status" aria-live="polite"></div><script src="{BASE}/assets/app.js" defer></script></body></html>'
def card(p):
 return f'''<article class="card" data-category="{e(p['category'])}" data-search="{e(p['title']+' '+p['summary']+' '+p['category'])}" data-slug="{p['slug']}"><a class="art {p['theme']}" href="{BASE}/posts/{p['slug']}/" tabindex="-1" aria-hidden="true"><span>{p['label']}</span><div class="art-mark">{'✳' if p['theme']=='blue' else '⌁' if p['theme']=='green' else '↗'}</div><small>날쌤의 기록 / {p['category']}</small></a><div class="card-body"><div class="meta">{p['category']}<span>{p['date'].replace('-','. ')}</span></div><h3><a href="{BASE}/posts/{p['slug']}/">{e(p['title'])}</a></h3><p>{e(p['summary'])}</p><div class="card-bottom"><a href="{BASE}/posts/{p['slug']}/">읽어보기 ↗</a><button data-save="{p['slug']}" aria-pressed="false" aria-label="{e(p['title'])} 저장">＋ 저장</button></div></div></article>'''
index=head('배움이 일상에 쓸모가 되는 곳','AI 활용부터 일상의 발견까지. 날쌤이 나누는 실용적인 지식과 기록.')+'''<main id="main"><section class="hero"><div><div class="eyebrow"><span></span> NALSSAM’S PERSONAL JOURNAL</div><h1>오늘의 발견이,<br>내일의 <em>쓸모</em>가 되도록.</h1><p>AI와 디지털, 그리고 우리 곁의 일상.<br>배우고 발견한 좋은 정보를 차곡차곡 나눕니다.</p><a class="primary" href="#browse">쓸모 있는 기록 둘러보기 <span>↗</span></a></div><div class="hero-art" aria-hidden="true"><div class="orbit"></div><span class="float one">작은 발견</span><span class="float two">새로운 연결 ↗</span><div class="note"><small>THE EVERYDAY EDIT</small><strong>배우고.<br>써 보고.<br>나누고.</strong><span>✳</span><div>GOOD THINGS, WORTH SHARING.</div></div></div></section><section class="intro-strip"><span>호기심은 넓게, 기록은 쓸모 있게.</span><span>기술과 생활 사이의 좋은 발견 <b>↙</b></span></section><section id="browse"><div class="section-head"><div class="eyebrow">EXPLORE THE NOTES</div><h2>어떤 기록을 찾으세요?</h2><label class="search">⌕ <input id="search" type="search" placeholder="궁금한 주제, 키워드로 검색" aria-label="기록 검색"></label></div><div class="filters" aria-label="카테고리 필터">'''+''.join(f'<button data-filter="{c}" aria-pressed="{str(c=="전체").lower()}">{c}</button>' for c in ['전체']+cats)+'''<div class="saved-toggle"><input id="saved-only" type="checkbox"><label for="saved-only">저장한 글만</label></div></div><div class="results-line"><span id="result-count"></span><span>차곡차곡 업데이트 중</span></div><div class="grid">'''+''.join(card(p) for p in posts)+'''</div><div id="empty" hidden><h3>아직 이곳에 담긴 기록은 없어요.</h3><p>다른 카테고리를 둘러보거나 검색어를 바꿔 보세요.</p><button id="reset">전체 기록 보기</button></div></section><section class="about-banner"><span class="about-symbol">n.</span><div><div class="eyebrow">HELLO, I’M NALSSAM</div><h2>교실에서 시작해, 일상으로 이어지는 기록.</h2><p>초등학교 교사 박준호, 날쌤입니다.<br>누군가에게 작지만 분명한 도움이 되는 공간을 만들어 갑니다.</p></div><a href="about/">조금 더 알아보기 ↗</a></section></main>'''+foot(); (D/'index.html').write_text(index)
for p in posts:
 path=f"posts/{p['slug']}/"; out=D/path;out.mkdir(parents=True,exist_ok=True)
 schema={'@context':'https://schema.org','@type':'BlogPosting','headline':p['title'],'description':p['summary'],'datePublished':p['date'],'dateModified':p['date'],'author':{'@type':'Person','name':'박준호','alternateName':'날쌤','url':BASE+'/about/'},'mainEntityOfPage':BASE+'/'+path}
 content=head(p['title'],p['summary'],path,schema)+f'<main id="main" class="article"><a class="back" href="{BASE}/#browse">← 모든 기록</a><div class="eyebrow">{p["category"]}</div><h1>{e(p["title"])}</h1><p class="lead">{e(p["summary"])}</p><div class="byline">날쌤 · {p["date"]}<button data-save="{p["slug"]}" aria-pressed="false">＋ 저장</button><button id="share">링크 공유 ↗</button></div><div class="prose">'+''.join('<p>'+e(v)+'</p>' for v in p['body'])+(f'<a class="source" href="{e(p["source"])}" rel="noopener">{e(p["sourceLabel"])} ↗</a>' if p.get('source') else '')+'</div><aside class="article-note">도움이 된 글은 저장해 두세요. 저장 목록은 이 브라우저에만 보관됩니다.</aside></main>'+foot();(out/'index.html').write_text(content)
for slug,title,body in [('about','날쌤 소개','<p>초등학교 교사이자 몽당분필 대표 박준호입니다. 온라인에서는 날쌤이라는 이름으로 교육과 기술에 관한 이야기를 나눕니다.</p><p>이곳은 AI 활용과 디지털 팁에서 시작해 생활 속 발견을 함께 나누는 개인 기록 공간입니다. 직접 경험한 것과 일반적인 안내를 구분하고, 달라질 수 있는 정보는 작성 시점을 함께 남깁니다.</p><p>추천 가전제품·맛집·카페·여행지·화장품·책은 앞으로 기록을 모아 갈 카테고리입니다. 아직 게시하지 않은 경험을 실제 후기처럼 채우지 않았습니다.</p><a href="https://blog.naver.com/nalssam">날쌤 네이버 블로그 ↗</a>'),('admin','글 작성과 발행','<p>이 사이트는 GitHub Pages로 공개되며, 글 수정과 발행 권한은 GitHub 저장소 권한으로 관리합니다. 이 페이지 자체가 로그인 화면은 아닙니다.</p><h2>GitHub에서 로그인하고 편집하기</h2><p>아래 버튼으로 GitHub 편집기에 이동합니다. 저장소 소유자 계정으로 로그인하고 content/posts.json에 글을 추가한 뒤 커밋하면 자동 빌드·발행됩니다. 방문자는 직접 발행할 수 없습니다.</p><a class="primary" href="https://github.com/nalssam/nalssam-life/edit/main/content/posts.json">GitHub 로그인 · 글 편집 ↗</a><h2>공개 전에 확인</h2><p>저장소가 공개이므로 파일에 넣은 초안도 공개됩니다. 비공개 초안, 개인정보, 학생 정보, 비밀번호를 넣지 마세요. 별도의 사이트 내 관리자 로그인과 비공개 초안 저장 기능은 아직 연결하지 않았습니다.</p><p>사진에 사람이 보이면 얼굴만 모자이크한 이미지를 사용합니다. 지도·가격·운영시간처럼 변동되는 정보는 확인 날짜와 출처를 기록합니다.</p>')]:
 out=D/slug;out.mkdir(exist_ok=True);(out/'index.html').write_text(head(title,title,slug+'/',noindex=slug=='admin')+f'<main id="main" class="article"><div class="eyebrow">NALSSAM’S JOURNAL</div><h1>{title}</h1><div class="prose">{body}</div></main>'+foot())
(D/'404.html').write_text(head('페이지를 찾을 수 없습니다','페이지를 찾을 수 없습니다',noindex=True)+f'<main id="main" class="article"><h1>기록을 찾지 못했어요.</h1><a href="{BASE}/">첫 화면으로 돌아가기 →</a></main>'+foot())
shutil.copytree(P/'assets',D/'assets',dirs_exist_ok=True);(D/'.nojekyll').touch()
urls=[BASE+'/',BASE+'/about/']+[BASE+'/posts/'+p['slug']+'/' for p in posts]
(D/'sitemap.xml').write_text('<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'+''.join('<url><loc>'+e(u)+'</loc></url>' for u in urls)+'</urlset>')
(D/'robots.txt').write_text(f'User-agent: *\nAllow: /\nSitemap: {BASE}/sitemap.xml\n')
(D/'feed.xml').write_text('<?xml version="1.0" encoding="UTF-8"?><rss version="2.0"><channel><title>날쌤의 쓸모 있는 기록</title><link>'+BASE+'</link><description>배움과 일상의 기록</description>'+''.join('<item><title>'+e(p['title'])+'</title><link>'+BASE+'/posts/'+p['slug']+'/</link><guid>'+BASE+'/posts/'+p['slug']+'/</guid><description>'+e(p['summary'])+'</description></item>' for p in posts)+'</channel></rss>')
print(f'Built {len(posts)} posts into {D}')
